insert into public.questions (id, test_id, prompt, options, position, passage) values
  ('0d56fa41-2c41-5c79-920d-4fa5e053b451', 'bbd5c696-a0ae-5b92-a059-830a2175afb5', 'As used in the text, what does the word “surveyed” most nearly mean?', '["Looked at", "Had questions about", "Organized", "Was captivated by"]'::jsonb, 1, 'The following text is from Mark Twain’s 1876 novel The Adventures of Tom Sawyer. Tom, a child, has been told by his aunt to paint their house’s fence.

Tom appeared on the sidewalk with a bucket of whitewash and a long-handled brush. He <u>surveyed</u> the fence, and all gladness left him and a deep melancholy settled down upon his spirit. Thirty yards of board fence nine feet high.'),
  ('28198fd2-07e1-5a2d-a786-d5d812a11df2', 'bbd5c696-a0ae-5b92-a059-830a2175afb5', 'Which choice completes the text with the most logical and precise word or phrase?', '["predictable", "timeworn", "innovative", "idealistic"]'::jsonb, 2, 'Though most studies of the effect of altitude on blood chemistry usually concentrated on people who live above sea level, researchers Suleiman A. Al-Sweedan and Moath Alhaj have instead chosen the _____ path in their recent work of studying the blood of people who live below sea level, in locations such as the California towns of Salton City and Imperial.'),
  ('d6a49533-06f0-5cf3-831d-6e9f31a702d5', 'bbd5c696-a0ae-5b92-a059-830a2175afb5', 'Which choice completes the text with the most logical and precise word or phrase?', '["counteract", "accentuate", "rectify", "obscure"]'::jsonb, 3, 'The Gleaners, painted in the realist style by Jean-Francois Millet, depicts peasants picking stray wheat from a field after the harvest. The realists’ emphasis on accurately portraying the experiences of average working people was largely a rejection of the romantic style evident in many paintings by Jérôme-Martin Langlois, which instead _____ their subjects’ beauty or heroism while hiding all imperfection.'),
  ('d27da07a-b82b-5b1e-a4e6-4ff443259cc4', 'bbd5c696-a0ae-5b92-a059-830a2175afb5', 'Which choice completes the text with the most logical and precise word or phrase?', '["nebulous", "intricate", "unprecedented", "concrete"]'::jsonb, 4, 'Although our knowledge of the Pliocene epoch and the lives of the hominids during this time was once _____, recent analyses of fossils like that of the individual known as KNM-KP 271, discovered in Kenya in 1963, have sharpened our picture of what a day in the life of KNM-KP 271 may have looked like.'),
  ('ea661307-051b-5a55-b8b3-831e4767dd18', 'bbd5c696-a0ae-5b92-a059-830a2175afb5', 'Which best describes the overall structure of the text?', '["It discusses two cultural centers operated by tribes, then compares them with non-Indigenous institutions that present Indigenous exhibits.", "It describes how tribal cultural centers designed exhibits of a particular set of art, then analyzes how non-Indigenous institutions designed exhibits of the same artifacts.", "It outlines an early strategy for exhibit design used by one tribal cultural center, then exploits a newer strategy used by a different tribal cultural center.", "It examines how tribal citizens responded to exhibits at tribal cultural centers, then speculates how non-Indigenous audiences would respond to the same exhibits."]'::jsonb, 5, 'In what is now Washington state, the Tulalip Tribes operate the Hibulb Cultural Center. Relying on traditional knowledge to guide the design of exhibits, this institution presents Tulalip history and culture to the tribe’s citizens. The Citizen Potawatomi Nation, a tribe in Oklahoma, employs a similar strategy in its own cultural center. Both centers contrast with museums that aren’t Indigenous-led; when displaying Indigenous artifacts, such museums tend to anticipate mainly non-Indigenous audiences and rely on Euro-centric strategies for designing exhibits.'),
  ('36ddc3f2-c843-54f6-adf0-7de744c8c848', 'bbd5c696-a0ae-5b92-a059-830a2175afb5', 'Which choice best states the main purpose of the text?', '["To describe the effect of human-scaled architecture on any given city’s walkability.", "To explain why it is challenging to compare the amount of pedestrian traffic in different cities.", "To present a claim about how individuals’ decision-making about walking can be improved.", "To discuss the difficulty of identifying a reliable way to increase walking in any given city."]'::jsonb, 6, 'Luang Prabang has high pedestrian traffic, but simply replicating a feature of Luang Prabang associated with walkability—e.g., its human-scaled architecture—may be insufficient to induce increased walking in other cities. As urbanist Mariela Alfonzo argues, our understanding of individuals’ decision-making about whether to walk is insufficiently robust: some studies emphasize the role of local norms, others the role of demographic characteristics, and so on, but walking decisions are made in complex context in which multiple conditions and needs inform individuals’ choices.'),
  ('883aa10b-dc64-53c2-b04d-a5989636edfe', 'bbd5c696-a0ae-5b92-a059-830a2175afb5', 'Which choice best describes the function of the underlined part?', '["It elaborates on the description of reduplication by exemplifying how it works in the specific Hoocak word mentioned earlier.", "It provides English translation of the Hoocak word mentioned earlier.", "It acknowledges that Hoocak has some important exceptions to the general pattern described earlier.", "It emphasizes how frequently reduplication occurs in Hoocak."]'::jsonb, 7, 'In Hoocak, an Indigenous language from the Mid-Atlantic region of what is now the United States, okayeke means “bad,” whereas ati okayeye’tesel means “bad houses.” This phenomenon, in which an element of a root word is repeated, sometimes with modification, within another word that is related to the root word, is called reduplication. <u>In this case, the element “ye” in okayeke gets repeated in ati</u> <u>okayeye’tesel.</u> There are many examples of this type of reduplication in Hoocak.'),
  ('029b6b8a-2043-5568-88b6-f29b5857675c', 'bbd5c696-a0ae-5b92-a059-830a2175afb5', 'According to the text, what is one potential drawback of Hidalgo and colleagues’ method?', '["It depends upon data that are likely to be outdated.", "It is based on recent advancements from other fields that have yet to be applied outside of those contexts.", "It may lead to conclusions that are not reflective of all the amenities in a given neighborhood.", "It is likely to contribute to inaccurate identifications of the boundaries of specific neighborhoods."]'::jsonb, 8, 'Researcher César A. Hidalgo, Elisa Castaner, and Andres Sevtsuk created a computer model to predict the mix of businesses and places of interest found in a given neighborhood. The team used data from the Google Places API service to help identify furniture stores, florists, and other businesses and map their locations. This approach has some limits—data from Places API tend to be restricted to places that are customer facing—but the data set nonetheless provides an extremely reliable source to study colocation patterns of neighborhood amenities.'),
  ('2882234b-c72c-5e33-a1e5-44b8c29f399a', 'bbd5c696-a0ae-5b92-a059-830a2175afb5', 'According to the text, how did Hooks and Ward initially meet?', '["Hooks and Ward participated in the same workshop at NEC.", "Hooks and Ward attended the same performance of The Great MacDaddy.", "Harrison introduced Hooks to Ward at a performance of The Great MacDaddy.", "Hooks and Ward were both actors in a production of A Raisin in the Sun."]'::jsonb, 9, 'The groundbreaking Negro Ensemble Company (NEC), founded in 1967, produced Paul Carter Harrison’s award-winning play The Great MacDaddy in 1974. The company was cofounded by Robert Hooks, an actor, producer, and activist, and actor and playwright Douglas Turner Ward, who had met while performing in a 1960 touring production of Lorraine Hansberry’s play A Raisin in the Sun. They shared a vision of a theater company that would nurture and showcase the work of Black theater professionals. Since its beginning, NEC has provided a forum for the voices of Harrison and other Black playwrights through workshops and performances.'),
  ('a208ff8f-a459-54a4-8928-cb29d9756233', 'bbd5c696-a0ae-5b92-a059-830a2175afb5', 'Which quotation from Poems most effectively illustrates the claim?', '["“God bless our native land, / Her homes and children bless, / Oh may she ever stand / For truth and righteousness.” (from “God Bless Our Native Land”)", "“Men may tread down the poor and lowly, / May crush them in anger and hate, / But surely the mills of God’s justice / Will grind out the grist of their fate.” (from “An Appeal to My Countrywomen”)", "“Say not the age is hard and cold— / I think it brave and grand; / When men of diverse sects and creeds / Are clasping hand in hand.” (from “The Present Age”)", "“When ye plead for the wrecked and fallen, / The exile from far-distant shores, / Remember that men are still wasting / Life’s crimson around your own doors.” (from “An Appeal to My Countrywomen”)"]'::jsonb, 10, 'Poems is an 1896 collection of poetry by Frances E. W. Harper. In one of Harper’s poems, the speaker criticizes activists who champion humanitarian causes in other countries while overlooking local concerns, saying _____'),
  ('acf711d1-9c95-56db-af36-2e333604ff3c', 'bbd5c696-a0ae-5b92-a059-830a2175afb5', 'Which choice most effectively uses data from the table to complete the comparison?', '["below wholesale trade but above both professional services and administration/waste.", "above all three of the other industries listed in the table.", "below all three of the other industries listed in the table.", "above either administration/waste or professional services and nearly equal to wholesale trade."]'::jsonb, 11, '**Impact of Four Key Industries on Oklahoma Economy in 2017**

| Industry | Approximate total contribution by industry | Number of people employed by industry | Average contribution per employee by industry |
| Professional services | \$7,694,000,000 | 59,846 | \$110,157 |
| Tribal economic activity | \$7,312,400,000 | 51,674 | \$141,510 |
| Administration/waste | \$5,830,600,000 | 96,964 | \$60,132 |
| Wholesale trade | \$10,723,400,000 | 58,346 | \$183,790 |

The Cherokee Nation, the Seminole Nation, and the more than thirty other tribes in Oklahoma operate numerous businesses and generate billions of dollars in revenue. An economics student is researching the tribes’ collective activity as a single industry. The student wants to compare the average amount contributed per employee to Oklahoma’s economy with the average amount contributed per employee by three other industries. Looking at the table, the student finds that tribal economic activity contributed over \$141,000 per employee, on average, ranking it _____'),
  ('0b6f5b49-75f0-5564-a11d-d74ff8aa8036', 'bbd5c696-a0ae-5b92-a059-830a2175afb5', 'Which choice most effectively uses data from the graph to complete the assertion?', '["difference between the forest cover area in Class I-IV and in Class VI in 2000.", "increase in the forest cover area for all classes from 1979 to 2000.", "decrease in the forest cover area for all classes from 1960 to 1979.", "similarity in forest cover area in Class I-IV and Class VII in 1986."]'::jsonb, 12, '![figure](/q/aug23/001.webp)

To understand the extent of deforestation in the Chorotega Region of Costa Rica, Juan Pablo Arroyo-Mora and colleagues used aerial photography and remote sensing data to track changes in the forest cover area across different land use capability class (categories that indicate possible uses of forest land.) Due to the Chorotega region’s accessibility, various types of forest areas were converted to cattle practices as rising international meat prices drove a cattle ranching boom in the 1960s and 1970s. By the mid 1980s, however, increased public awareness and environmental reforms, along with a decline in meat prices, engendered a natural forest regrowth, as evident by the _____'),
  ('7e0a93f5-bf32-5923-8e0c-ea87fb652067', 'bbd5c696-a0ae-5b92-a059-830a2175afb5', 'Which finding, if true, would most directly support Bura and colleagues’ claim?', '["In most cases, the sound that a caterpillar species produced during simulated attacks was not produced by other caterpillar species during simulated attacks.", "Chickens and yellow warblers, two predators of caterpillars, have been observed to stop their attacks in response to caterpillar sounds.", "Caterpillar clicks were emitted in a frequency detectable by birds that prey on caterpillars, but caterpillar whistles were not.", "Each caterpillar species tended to produce one sound during simulated attacks, although individuals occasionally made a variety of other sound during simulated attacks as well."]'::jsonb, 13, 'Veronica L. Bura, Akito Y. Kawahara, and Jayne E. Yack investigated the evolution and function of sound production in silk moth and hawk moth caterpillars. They found that during harmless simulated attacks on isolated caterpillars, 33% of the tested species produced sound, which ranged from clicks in Manduca pellenia to whistles in Rhodinia fugax. Although some insects use sound to communicate with members of the same species, the researchers claim that the caterpillar sounds recorded in their study are directed primarily at predators.'),
  ('71c52cc8-e61d-5511-8096-f6610ba616f5', 'bbd5c696-a0ae-5b92-a059-830a2175afb5', 'Which choice most logically completes the text?', '["some hoards contained no gold, as was the case for the Parc-y-Meirch hoard.", "most Bronze Age gold objects were melted down so that the gold could be reused.", "the skills needed to make tools and weapons from bronze were easy to adapt to making decorative items from gold.", "some hoards were found as a result of artifacts being dug up by accident."]'::jsonb, 14, 'The British Bronze Age began when sophisticated techniques for making tools, weapons, and other objects from metal were introduced to the British Isles around 2500 BCE, and it lasted until around 700 BCE. In Britain during this time, collections of valuable metal objects (called hoards) were sometimes buried for safekeeping. Some stayed buried for many centuries, such as the Parc-y-Meirch hoard, which was unearthed around 1868, and the Fittleworth hoard, discovered in 1995. And although the period is known as the Bronze Age, some hoards, like the Fittleworth hoard, contained decorative objects made of gold; gold was much rarer than bronze, however, and thus it is not surprising that ______'),
  ('b10bce0b-e78d-5ccf-a845-a219a57b4298', 'bbd5c696-a0ae-5b92-a059-830a2175afb5', 'Which choice most logically completes the text?', '["it’s useful at present for North Dakota to distinguish between invasive and native species in some instances but not in the case of the spiny water flea.", "North Dakota was previously home to some spiny water flea but they were outcompeted by invading species.", "states such as North Dakota may need to reevaluate their classifications of species.", "North Dakota should coordinate with other states to prevent their native species from invasive species."]'::jsonb, 15, 'The state of North Dakota has designated the spiny water flea as an invasive species that could outcompete some of the state’s native species. Many other states draw similar distinctions between invasive and native species. But researchers Alejandro Camacho and Jason McLachlan have pointed out that Earth’s climate is changing in ways that challenge such designations. Climate changes may cause animals to leave their current ranges and establish new ones. Climate changes may also create good habitats in areas where a species couldn’t live previously. These observations suggest that _____'),
  ('49a8d358-4f3d-509a-8d55-979b0f332f2a', 'bbd5c696-a0ae-5b92-a059-830a2175afb5', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["explains", "explain", "have explained", "are explaining"]'::jsonb, 16, 'Water boils at around 212 °F at sea level, but in Highland, Utah (elevation: 4,977 feet above sea level), it boils at around 202 °F. Food writer J. Kenji López-Alt, who explores the science behind cooking, _____ that lower boiling points at higher elevations “can wreak all sorts of havoc on recipes.”'),
  ('e9b041d3-5faa-500a-9498-7a514af80fc1', 'bbd5c696-a0ae-5b92-a059-830a2175afb5', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["housing", "to house", "to have housed", "houses"]'::jsonb, 17, 'It is widely known that New York City’s Museum of Modern Art (MoMA) _____ a vast collection of oil paintings, including Franz Marc’s The World Cow and Katherine S. Dreier’s Abstract Portrait of Marcel Duchamp.'),
  ('0fa3c091-b3bf-505f-9a6d-a74562d68284', 'bbd5c696-a0ae-5b92-a059-830a2175afb5', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["these", "they", "we", "it"]'::jsonb, 18, 'Lily Everett and Mary Foote were among the 300 artists who exhibited at the 1913 Armory Show, a groundbreaking New York City art exhibition that introduced modernism to American audiences. Marcel Duchamp’s abstract cubist aesthetic received the most skepticism from critics, as _____ represented a radical departure from the more realistic painting style that was popular at the time.'),
  ('6b4d0c1d-936c-57e9-b978-6cc7d8709f64', 'bbd5c696-a0ae-5b92-a059-830a2175afb5', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["has risen", "rises", "rising", "rose"]'::jsonb, 19, 'In Moscow, Russia, the average temperature is 62.6 degrees Fahrenheit in June, _____ to 66.6 degrees in July, and then dips slightly to 62.6 degrees in August.'),
  ('b524f075-bc45-5cbb-9b22-693d60cd4c90', 'bbd5c696-a0ae-5b92-a059-830a2175afb5', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["Congress.", "Congress:", "Congress;", "Congress"]'::jsonb, 20, 'After finding information about Major Robert Odell Owens, who represented New York in the United States House of Representatives, the student discovered biographical sketches of two other Black Americans who served in _____ Josiah Thomas Walls of Florida and Tomas Ezekiel Miller of South Carolina.'),
  ('5cb5834f-62bd-5e77-9245-fb293610bac0', 'bbd5c696-a0ae-5b92-a059-830a2175afb5', 'Which choice completes the text with the most logical transition?', '["rather,", "finally,", "as a result,", "similarly,"]'::jsonb, 21, 'The first documented use of the English word “depart” is attributed to poet Geoffrey Chaucer’s 1386 work The Parson’s Tale. However, Chaucer didn’t write in Modern English; _____ he wrote in what we now call Middle English, which was commonly used during the period.'),
  ('603d8aad-2ba5-5a46-93c0-1ade42d6059f', 'bbd5c696-a0ae-5b92-a059-830a2175afb5', 'Which choice completes the text with the most logical transition?', '["Still,", "Conversely,", "Fittingly,", "Nowadays,"]'::jsonb, 22, 'In his essay “Of Coaches,” French philosopher Michel de Montaigne explores a relatively light subject, but he addresses heavier fare in “Of the Inconvenience of Greatness.” Regardless of subject matter, Montaigne works to question his own perspective throughout his essays. _____ his personal motto was “What do I know?”'),
  ('9bd19bb9-3ba6-52fc-aa4d-f2f66c2a8ba9', 'bbd5c696-a0ae-5b92-a059-830a2175afb5', 'Which choice completes the text with the most logical transition?', '["Fittingly,", "Granted,", "For example,", "More often,"]'::jsonb, 23, 'Blanche K. Bruce was an outspoken abolitionist whose Washington, DC, home was a stop on the underground railroad (the network of people and places that some enslaved people used to escape to freedom). It was relatively rare for supporters of the railroad to be secretive about their antislavery views. _____ they were vocal abolitionists like Bruce.'),
  ('6e5c7afa-4b18-58fa-a30d-2d011cc5e701', 'bbd5c696-a0ae-5b92-a059-830a2175afb5', 'The student wants to emphasize the similarity between the two mountain ranges. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["There are dozens of different mountain ranges located in the southwestern US and northwestern Mexico.", "The Archipelago-Madrean Mountains and the Big Hatchet mountains are both inland mountain ranges whose surroundings are different from those of the surrounding mountains.", "2\nThe Archipelago-Madrean Mountains cover an area of 1,038 mi, while the Big Hatchet 2\nMountains cover an area of 65 mi.", "Even though they are both sky inlands, the Archipelago-Madrean Mountains and the Big Hatchet Mountains are located in different countries."]'::jsonb, 24, 'While researching a topic, a student has taken the following notes:

The Archipelago-Madrean Mountains are located in northwestern Mexico.
2
They cover an area of 1,038 square miles (mi).
The Big Hatchet Mountains are located in the southwestern United States.
2
They cover an area of 65 mi.
These mountain ranges are two of the dozens of “sky inlands” in the southwestern US and northwestern Mexico.
A sky inland is an isolated mountain range whose environment differs dramatically from that of the surrounding lowlands.'),
  ('d844a66a-3fa7-5e5c-a9b3-78818ffd6071', 'bbd5c696-a0ae-5b92-a059-830a2175afb5', 'The student wants to provide a quotation from chapter 17. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["After discussing themes of nostalgia in Joseph Brodsky’s writing, Svetlana Boym goes on to discuss various skeptics’ takes on the concept of nostalgia.", "Svetlana Boym’s The Future of Nostalgia is a multifaceted exploration of nostalgia.", "In an exploration of various skeptics’ takes on the concept of nostalgia, Svetlana Boym writes, \"The poethics of nostalgia combines estrangement and human solidarity, affect and reflection.\"", "Svetlana Boym discusses themes of nostalgia in Joseph Brodsky’s writing in chapter 14 of her book."]'::jsonb, 25, 'While researching a topic, a student has taken the following notes:

The Future of Nostalgia is a scholarly book by literary theorist Svetlana Boym.
The book provides a multifaced exploration of the concept of nostalgia.
Chapter 14 discusses themes of nostalgia in Joseph Brodsky’s writing.
Chapter 17 discusses various skeptics’ takes on the concept of nostalgia.
In chapter 17, Boym writes, "The poethics of nostalgia combines estrangement and human solidarity, affect and reflection."'),
  ('f42711b3-1824-5b93-bfd1-d9de9d62fa49', 'bbd5c696-a0ae-5b92-a059-830a2175afb5', 'The student wants to specify the cup’s name in Choctaw. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["The Hina Hanta archive features cultural artifacts, such as a cup and a stickball collar, that are relevant to the history of the Choctaw people.", "The clay cup, which is included in the Hina Hanta online archive, is called an isht ishko in Choctaw.", "Hina Hanta, which means “bright path” in Choctaw, includes a cup in its archive.", "The name of the online archive Hina Hanta means “bright path” in Choctaw."]'::jsonb, 26, 'While researching a topic, a student has taken the following notes:

Hina Hanta is an online archive curated by the Choctaw Nation of Oklahoma.
Hina Hanta means “bright path” in Choctaw.
It features images of cultural artifacts relevant to the history of the Choctaw people. It includes a cup (isht ishko in Choctaw) made from clay.
It includes a stickball collar (innuchi) made from horsehair.'),
  ('e000515f-a98d-592c-9963-eb3aad30f161', 'bbd5c696-a0ae-5b92-a059-830a2175afb5', 'The student wants to specify how long Mozambique officially used the escudo. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Countries sometimes adopt new currency systems, as Mozambique did when it replaced the escudo with the metical.", "Though Mozambique currently uses the metical, the country’s former official currency was introduced in 1914.", "The escudo was Mozambique’s official currency from 1914 to 1980.", "The metical has been Mozambique’s official currency since 1980, when it replaced the escudo."]'::jsonb, 27, 'While researching a topic, a student has taken the following notes:

A currency is a money system.
Sometimes, countries adopt a new currency to replace an older one.
Mozambique adopted the escudo as its official currency in 1914.
The metical replaced the escudo in 1980.
The metical remains Mozambique’s official currency.')
on conflict (id) do update set test_id = excluded.test_id, prompt = excluded.prompt, options = excluded.options,
  position = excluded.position, passage = excluded.passage;
insert into public.question_keys (question_id, correct_index, correct_answers, explanation) values
  ('0d56fa41-2c41-5c79-920d-4fa5e053b451', 0, null, '**Choice A is correct.** In the sentence, Tom "appeared on the sidewalk with a bucket of whitewash and a long-handled brush. He surveyed the fence, and all gladness left him..." The surrounding context shows Tom looking at the fence and reacting to its size and task; "surveyed" therefore means he examined or looked at the fence.
**Choice B is incorrect.** "Had questions about" implies uncertainty or asking, but the passage indicates a visual assessment causing melancholy, not questioning.
**Choice C is incorrect.** "Organized" would mean arranging or putting in order, which does not match Tom’s reaction to seeing the large fence.
**Choice D is incorrect.** "Was captivated by" suggests delight or fascination; the text explicitly says "all gladness left him," so he was not captivated.
**Faster approach:** Use context clues immediately before and after the word—Tom’s reaction (loss of gladness and melancholy) shows he simply looked at and assessed the large fence.'),
  ('28198fd2-07e1-5a2d-a786-d5d812a11df2', 2, null, '**Choice C is correct.** The sentence contrasts the common approach—studying people who live above sea level—with the researchers'' different approach of studying people who live below sea level. The most logical, precise word to describe this contrary approach is "innovative," which conveys that their choice departs from the usual practice in a novel way.
**Choice A is incorrect.** "Predictable" would imply their choice was expected or typical, which contradicts the contrast set up in the sentence.
**Choice B is incorrect.** "Timeworn" means old or overused; it doesn’t fit because the sentence emphasizes a departure from the usual method, not an old one.
**Choice D is incorrect.** "Idealistic" suggests motivated by ideals rather than practicality; the sentence focuses on novelty relative to standard studies, not the researchers'' motives.
**Faster approach:** Look for the contrast clue ("instead") and pick the word meaning "new or different"—i.e., "innovative."'),
  ('d6a49533-06f0-5cf3-831d-6e9f31a702d5', 1, null, '**Choice B is correct.** The sentence contrasts the realist emphasis on "accurately portraying the experiences of average working people" with the romantic style, which does the opposite by emphasizing positive features: it "accentuate[s] their subjects’ beauty or heroism while hiding all imperfection." "Accentuate" precisely means to make more noticeable or prominent, which fits the pair of praising and concealing actions described.
**Choice A is incorrect.** "Counteract" means to oppose or neutralize, which does not fit the idea that romantic painters highlighted beauty or heroism.
**Choice C is incorrect.** "Rectify" means to correct; that meaning is unrelated to praising or idealizing subjects in the way the sentence requires.
**Choice D is incorrect.** "Obscure" means to hide or make unclear; while the sentence does mention "hiding all imperfection," the verb for the first blank must indicate emphasizing positive traits, not hiding them.
**Faster approach:** Predict the meaning that belongs in the blank (a verb meaning "emphasize or glorify") from the surrounding context, then eliminate choices that mean the opposite or are unrelated.'),
  ('d27da07a-b82b-5b1e-a4e6-4ff443259cc4', 0, null, '**Choice A is correct.** The sentence contrasts the earlier state of knowledge with the effect of recent analyses: if those analyses "have sharpened our picture," the prior knowledge must have been unclear or indistinct. "Nebulous" means vague or ill-defined, so it fits the contrast and yields a logically coherent sentence.
**Choice B is incorrect.** "Intricate" means complex or detailed; saying knowledge was once intricate would not contrast well with analyses that "sharpened our picture," which implies clarification rather than increased complexity.
**Choice C is incorrect.** "Unprecedented" means never before seen; that meaning does not set up a contrast with sharpening a picture of past lives and therefore does not make sense in context.
**Choice D is incorrect.** "Concrete" means clear and specific; if knowledge had already been concrete, recent analyses would not be said to have "sharpened" the picture in the same way. The intended contrast calls for a word meaning vague, not clear.
**Faster approach:** Look for the contrast introduced by "have sharpened" and pick a word meaning vague or unclear; eliminate options that mean clear, complex, or unrelated meanings.'),
  ('ea661307-051b-5a55-b8b3-831e4767dd18', 0, null, '**Choice A is correct.** The passage first describes two tribal cultural centers (the Hibulb Cultural Center and the Citizen Potawatomi Nation’s center) and the similar strategy they use, then explicitly contrasts those centers with non-Indigenous museums that present Indigenous artifacts. The sentence beginning "Both centers contrast with museums that aren’t Indigenous-led" signals the shift from description of the tribal centers to a comparison with other institutions.
**Choice B is incorrect.** The passage does not say the tribal centers and non-Indigenous institutions displayed the same particular set of art, nor does it analyze design of the same artifacts; it broadly contrasts strategies and intended audiences.
**Choice C is incorrect.** The passage does not present an "early" versus "newer" strategy or claim one center uses a different temporal approach; it says both employ a similar strategy.
**Choice D is incorrect.** The passage does not report how tribal citizens responded to exhibits or speculate about audience reactions; it describes who the centers present to (the tribe’s citizens) and how non-Indigenous museums anticipate mainly non-Indigenous audiences.
**Faster approach:** For structure questions, scan for transitional words (e.g., "both contrast", "then", "however") to identify whether the passage primarily describes, compares, or contrasts elements; that immediately points to the correct answer.'),
  ('36ddc3f2-c843-54f6-adf0-7de744c8c848', 3, null, '**Choice D is correct.** The passage argues that simply copying features associated with walkability (like human-scaled architecture) is often not enough to increase walking because people’s decisions are influenced by a complex mix of norms, demographics, and needs; thus the main purpose is to show the difficulty of identifying a reliable way to increase walking in any given city.
**Choice A is incorrect.** The passage does not describe the effect of human-scaled architecture on walkability in detail; it instead says that replicating such features may be insufficient.
**Choice B is incorrect.** The passage doesn’t compare amounts of pedestrian traffic between cities or explain measurement challenges; it focuses on why interventions may not reliably produce more walking.
**Choice C is incorrect.** The passage does not present a method to improve decision-making about walking; it states that understanding of those decisions is insufficiently robust.
**Faster approach:** For main-purpose questions, restate the passage’s concluding claim in your own words and eliminate choices that focus on details or propose actions not in the passage.'),
  ('883aa10b-dc64-53c2-b04d-a5989636edfe', 0, null, '**Choice A is correct.** The underlined sentence explicitly shows how reduplication operates in the provided example: it points out that the element “ye” from okayeke is repeated in ati okayeye’tesel, which is exactly an exemplification of the process just defined. This elaboration connects the general definition of reduplication to the specific Hoocak words given earlier.
**Choice B is incorrect.** The underlined sentence does not translate a Hoocak word into English; the passage already gave translations (okayeke = “bad,” ati okayeye’tesel = “bad houses”), and the underlined sentence instead describes how the element is repeated.
**Choice C is incorrect.** The sentence does not mention exceptions or departures from the pattern; it illustrates the pattern occurring in this example.
**Choice D is incorrect.** The sentence shows a single example of reduplication rather than making a claim about how frequently reduplication occurs.
**Faster approach:** For questions about a sentence’s function, ask whether it defines, exemplifies, contrasts, or quantifies; here the sentence clearly exemplifies the definition, so choose the answer that says “gives an example.”'),
  ('029b6b8a-2043-5568-88b6-f29b5857675c', 2, null, '**Choice C is correct.** The passage notes that the Google Places API data "tend to be restricted to places that are customer facing," which means the data set may not include every type of amenity in a neighborhood; therefore conclusions based on that data might not reflect all neighborhood amenities.
**Choice A is incorrect.** The passage does not say the data are outdated; it mentions a restriction in coverage (customer-facing places), not timeliness.
**Choice B is incorrect.** The passage does not claim the method relies on untested advancements from other fields; it describes using existing Google Places API data and a computer model.
**Choice D is incorrect.** The passage does not say the method causes inaccurate identification of neighborhood boundaries; it only cites limited coverage of certain types of places.
**Faster approach:** Look for the sentence describing limitations (words like "limits" or "restricted") and match that wording to the answer that describes missing or excluded data.'),
  ('2882234b-c72c-5e33-a1e5-44b8c29f399a', 3, null, '**Choice D is correct.** The passage states that Hooks and Ward "had met while performing in a 1960 touring production of Lorraine Hansberry’s play A Raisin in the Sun," which directly supports that they were both actors in that production.
**Choice A is incorrect.** The passage describes NEC providing workshops later but does not say Hooks and Ward met in an NEC workshop; it explicitly says they met during the 1960 touring production.
**Choice B is incorrect.** They did not meet at a performance of The Great MacDaddy; that play was produced by NEC in 1974, and the meeting occurred earlier during A Raisin in the Sun.
**Choice C is incorrect.** Paul Carter Harrison is mentioned separately as a playwright whose work NEC produced; the passage does not say Harrison introduced Hooks to Ward or that any introduction occurred at The Great MacDaddy.
**Faster approach:** Scan the sentence that mentions how the founders met; key words like "had met while performing" and the play title immediately identify the correct choice.'),
  ('a208ff8f-a459-54a4-8928-cb29d9756233', 3, null, '**Choice D is correct.** The quotation explicitly contrasts pleading for those "from far-distant shores" with a reminder that "men are still wasting / Life’s crimson around your own doors," which directly expresses the speaker’s criticism of activists who help abroad while neglecting local suffering.
**Choice A is incorrect.** That patriotic stanza praises the native land and righteousness but does not address the contrast between overseas humanitarianism and local neglect called for in the claim.
**Choice B is incorrect.** This line condemns oppression and invokes divine justice, but it does not criticize doing foreign charitable work while ignoring problems at home.
**Choice C is incorrect.** This quotation celebrates unity among diverse people in the present age and does not discuss the tension between aiding distant others and attending to local needs.
**Faster approach:** Scan each choice for explicit contrast language (words like "far-distant" vs "own doors," "remember," or imperatives calling attention to local needs) and eliminate any choice that lacks such a direct contrast.'),
  ('acf711d1-9c95-56db-af36-2e333604ff3c', 0, null, '**Choice A is correct.** The table shows the average contribution per employee for tribal economic activity as \$141,510, which is less than wholesale trade’s \$183,790 and greater than professional services’ \$110,157 and administration/waste’s \$60,132. Thus tribal activity ranks below wholesale trade but above both of the other listed industries.
**Choice B is incorrect.** It claims tribal activity is above all three others, but wholesale trade’s average (\$183,790) is higher than tribal (\$141,510).
**Choice C is incorrect.** It claims tribal is below all three, but tribal exceeds professional services and administration/waste.
**Choice D is incorrect.** It says tribal is above either administration/waste or professional services and nearly equal to wholesale trade; tribal is not nearly equal to wholesale trade, which is substantially higher.
**Faster approach:** Scan the "Average contribution per employee" column and directly compare the three numeric values to the tribal figure; choose the option that matches those ordinal relationships.'),
  ('0b6f5b49-75f0-5564-a11d-d74ff8aa8036', 1, null, '**Choice B is correct.** The graph shows that forest area for each land-use class falls between 1960 and 1979 and then rises afterward; from 1979 to 2000 all three series increase, indicating regrowth that began by the mid-1980s and continued to 2000. This use of the plotted increases across all classes supports the passage’s claim about natural forest regrowth.
**Choice A is incorrect.** The difference between Class I–IV and Class VI in 2000 describes a specific numerical gap in 2000, but it does not directly show that regrowth occurred by the mid-1980s.
**Choice C is incorrect.** A decrease from 1960 to 1979 documents earlier deforestation, not the regrowth the sentence attributes to the mid-1980s.
**Choice D is incorrect.** Noting a similarity between Class I–IV and Class VII in 1986 is a comparison of values, but it does not clearly demonstrate the overall pattern of regrowth across all classes.
**Faster approach:** Scan the graph for trends before and after the key date (1979 vs. mid-1980s/2000); choose the answer that describes an increase across all series rather than a single-value comparison.'),
  ('7e0a93f5-bf32-5923-8e0c-ea87fb652067', 1, null, '**Choice B is correct.** The researchers claim the recorded caterpillar sounds are directed primarily at predators; direct evidence that predators respond to those sounds (for example, stopping an attack) most directly supports that claim. Observations that chickens and yellow warblers cease attacks upon hearing caterpillar sounds provide behavioral evidence linking the sounds to predator deterrence.
**Choice A is incorrect.** That finding would show sounds differ between species, which might argue against intraspecific communication but does not directly show the sounds function to influence predators.
**Choice C is incorrect.** Demonstrating that some sounds are detectable by predators and others are not gives mixed relevance; it does not directly show that predators alter behavior in response to the sounds.
**Choice D is incorrect.** Showing each species tends to produce a single sound during attacks says nothing about whether the sounds are aimed at or affect predators.
**Faster approach:** For questions about a behavior’s function, choose the option that shows the proposed audience (here, predators) actually reacts to that behavior — i.e., evidence of the audience’s response.'),
  ('71c52cc8-e61d-5511-8096-f6610ba616f5', 0, null, '**Choice A is correct.** The passage states that gold was much rarer than bronze and gives two hoards as examples, one (Fittleworth) that contained gold. Given gold’s rarity, it follows logically that many hoards would contain no gold; the Parc-y-Meirch hoard is presented as a contrasting example, so saying some hoards contained no gold fits smoothly and directly completes the sentence.
**Choice B is incorrect.** The passage offers no evidence about the fate of most Bronze Age gold objects or widespread melting for reuse; this introduces a new historical claim not supported by the text.
**Choice C is incorrect.** The passage does not discuss craftsmanship or how skills transferred between metals; this statement is unrelated and not implied by gold’s rarity.
**Choice D is incorrect.** Whether hoards were found accidentally is irrelevant to the point about gold’s rarity and is not supported by the passage.
**Faster approach:** For inference completions, pick the choice that directly follows from the connecting phrase (here, rarity) and the examples already given; eliminate choices that introduce unsupported new facts.'),
  ('b10bce0b-e78d-5ccf-a845-a219a57b4298', 2, null, '**Choice C is correct.** The passage explains that climate change can cause species to move into new areas or make previously unsuitable areas habitable, which directly undermines fixed labels of “invasive” and “native.” The natural conclusion is that states that currently classify species by those labels may need to reconsider those classifications in light of shifting ranges.
**Choice A is incorrect.** The passage doesn’t single out the spiny water flea as a special exception to the general problem — it uses the flea as an example of a broader issue, so saying classifications are useful except for this one case is unsupported.
**Choice B is incorrect.** The passage gives no information that North Dakota previously hosted spiny water fleas or that they were outcompeted; this adds facts not in the text.
**Choice D is incorrect.** Coordination with other states to prevent invasions is not implied by the passage; the passage focuses on how climate-driven range shifts challenge labels, not on interstate prevention efforts.
**Faster approach:** For inference questions, identify the passage’s central claim and choose the answer that restates or logically follows from that claim; eliminate choices that introduce new, unsupported facts or specific prescriptions.'),
  ('49a8d358-4f3d-509a-8d55-979b0f332f2a', 0, null, '**Choice A is correct.** The sentence’s main subject is the singular noun phrase "Food writer J. Kenji López-Alt," so the verb must be singular and agree with that subject: "explains that..." fits the present-tense description and completes the sentence grammatically.
**Choice B is incorrect.** "Explain" is a plural (or base-form) verb and does not agree with the singular subject "Food writer J. Kenji López-Alt."
**Choice C is incorrect.** "Have explained" uses the plural auxiliary "have," which does not agree with the singular subject; additionally, the present-tense context calls for a simple present verb.
**Choice D is incorrect.** "Are explaining" uses the plural auxiliary "are" and the progressive form, which does not agree with the singular subject and shifts the tense/aspect unnecessarily.
**Faster approach:** Identify the subject (a singular noun or name) and choose the verb form that agrees (singular present tense), so select the singular verb "explains."'),
  ('e9b041d3-5faa-500a-9498-7a514af80fc1', 3, null, '**Choice D is correct.** The clause introduced by "that" requires a finite verb to state a fact about MoMA in the present, so "houses" (simple present) correctly completes the sentence: "It is widely known that New York City’s Museum of Modern Art (MoMA) houses a vast collection..."
**Choice A is incorrect.** "housing" is a present participle and would create a sentence fragment or require a different structure (for example, "...MoMA, housing a vast collection, ..."). It does not fit after "that."
**Choice B is incorrect.** "to house" is an infinitive and cannot serve as the main verb of a finite clause introduced by "that."
**Choice C is incorrect.** "to have housed" is a perfect infinitive and likewise cannot function as the clause’s main finite verb; it also wrongly implies a completed action rather than a general present fact.
**Faster approach:** After "that," look for a finite verb that states a fact; eliminate infinitives and participles, choosing the simple present for general truths ("houses").'),
  ('0fa3c091-b3bf-505f-9a6d-a74562d68284', 3, null, '**Choice D is correct.** The antecedent of the pronoun is the singular noun phrase "Marcel Duchamp’s abstract cubist aesthetic," so the singular neuter pronoun "it" correctly agrees in number and reference: "...as it represented a radical departure..." This preserves clear pronoun-antecedent agreement and standard English usage.
**Choice A is incorrect.** "These" is a plural demonstrative pronoun and does not agree with the singular antecedent "aesthetic."
**Choice B is incorrect.** "They" is a plural pronoun and therefore fails to agree in number with the singular noun phrase.
**Choice C is incorrect.** "We" is a first-person plural pronoun and would incorrectly shift the perspective to the speaker(s); it does not refer back to the third-person singular antecedent.
**Faster approach:** Check pronoun-antecedent agreement quickly—match singular vs. plural and person (first/second/third) to pick the correct pronoun every time.'),
  ('6b4d0c1d-936c-57e9-b978-6cc7d8709f64', 1, null, '**Choice B is correct.** The sentence uses present-tense verbs to describe typical monthly temperatures: "is 62.6 ... in June" and "dips ... in August." To maintain parallelism and tense, the middle verb must be a simple present verb that agrees with the subject "the average temperature," so "rises" fits: "is 62.6 ... in June, rises to 66.6 ... in July, and then dips ... in August."
**Choice A is incorrect.** "has risen" is present perfect and implies a completed change prior to now; it breaks the simple-present parallel structure with "is" and "dips."
**Choice C is incorrect.** "rising" is a participle and would create a nonparallel phrase (a dangling modifier) rather than a main-verb form matching "is" and "dips."
**Choice D is incorrect.** "rose" is simple past and does not match the present-tense verbs elsewhere in the sentence, so it fails to maintain tense consistency and parallel structure.
**Faster approach:** Scan for verb tense and parallel structure; choose the simple-present verb that matches the other main verbs in the series (here, "rises").'),
  ('b524f075-bc45-5cbb-9b22-693d60cd4c90', 1, null, '**Choice B is correct.** A colon is the convention used to introduce examples or a list that directly follows an independent clause. The clause "two other Black Americans who served in Congress" is completed by naming those individuals, so a colon after "Congress" properly signals that the names that follow ("Josiah Thomas Walls of Florida and Tomas Ezekiel Miller of South Carolina") are examples of those Americans.
**Choice A is incorrect.** A period would end the sentence, leaving the following words as a sentence fragment rather than completing the thought.
**Choice C is incorrect.** A semicolon links independent clauses or separates complex list items; it does not appropriately introduce examples or a simple list of names.
**Choice D is incorrect.** No punctuation would create a run-on or an unclear connection between the clause and the names; a colon is required to introduce the examples.
**Faster approach:** When a clause is immediately followed by specific examples or a list that illustrates it, use a colon to introduce those examples.'),
  ('5cb5834f-62bd-5e77-9245-fb293610bac0', 0, null, '**Choice A is correct.** The sentence sets up a contrast between what Chaucer did not write (Modern English) and what he did write (Middle English). The transition "rather," signals that contrast and smoothly connects the negative statement to the corrective information: "Chaucer didn’t write in Modern English; rather, he wrote in what we now call Middle English."
**Choice B is incorrect.** "Finally" indicates sequence or conclusion and does not fit a sentence that needs to contrast two kinds of English.
**Choice C is incorrect.** "As a result" indicates cause and effect; the sentence provides a contrast, not a consequence.
**Choice D is incorrect.** "Similarly" indicates likeness, which contradicts the intended contrast between Modern and Middle English.
**Faster approach:** For transitions, identify whether the sentence needs contrast, cause, addition, or similarity; pick the word that matches that relationship (here, contrast → "rather").'),
  ('603d8aad-2ba5-5a46-93c0-1ade42d6059f', 2, null, '**Choice C is correct.** The sentence describes Montaigne’s habit of questioning his perspective, so a transition that expresses that this behavior is appropriate or expected fits best. "Fittingly, his personal motto was ''What do I know?''" logically connects the general statement about his essays to a specific motto that exemplifies that tendency.
**Choice A is incorrect.** "Still," signals a contrast or concession; nothing in the previous sentence calls for a contrasting idea.
**Choice B is incorrect.** "Conversely," means the opposite would follow, which does not match the supportive relationship here.
**Choice D is incorrect.** "Nowadays," introduces a time-frame that is irrelevant to the passage’s description of Montaigne.
**Faster approach:** Pick the transition that matches the logical relationship (support, contrast, time, or opposition) between sentences; here the second sentence supports the first, so choose a supportive/apt transition like "Fittingly."'),
  ('9bd19bb9-3ba6-52fc-aa4d-f2f66c2a8ba9', 3, null, '**Choice D is correct.** The first sentence says it was "relatively rare" for supporters to be secretive, so the next clause should indicate what usually happened instead. "More often," signals that what follows is the more common situation: that supporters were vocal abolitionists like Bruce.
**Choice A is incorrect.** "Fittingly," suggests a logical or appropriate connection but does not express the contrast between rare secrecy and the usual behavior.
**Choice B is incorrect.** "Granted," introduces a concession and would set up contrast with an opposing point, which doesn’t match the intended meaning here.
**Choice C is incorrect.** "For example," would introduce an instance, but the sentence needs a transition indicating frequency (what usually occurred), not merely an example.
**Faster approach:** Identify whether the preceding sentence sets up contrast, frequency, cause, or example; choose the transition that matches that relationship (here, a frequency contrast → "More often,").'),
  ('6e5c7afa-4b18-58fa-a30d-2d011cc5e701', 1, null, '**Choice B is correct.** The notes state that both ranges are “sky inlands,” defined as isolated mountain ranges whose environment differs dramatically from the surrounding lowlands. Choice B highlights the shared category (both are inland/isolated ranges with distinct surroundings), using the relevant shared characteristic to emphasize similarity.
**Choice A is incorrect.** It restates a general fact about the region (dozens of ranges) rather than emphasizing a similarity between these two specific ranges.
**Choice C is incorrect.** It compares their areas and therefore emphasizes a numerical difference rather than a similarity.
**Choice D is incorrect.** It emphasizes a contrast (different locations/countries) rather than the similarity the student wants to stress.
**Faster approach:** Scan the notes for a shared descriptor (a category or definition both items are placed in); choose the answer that repeats that shared descriptor to show similarity.'),
  ('d844a66a-3fa7-5e5c-a9b3-78818ffd6071', 2, null, '**Choice C is correct.** The student’s notes indicate that chapter 17 discusses skeptics’ takes on nostalgia and that chapter 17 contains the sentence, "The poethics of nostalgia combines estrangement and human solidarity, affect and reflection." This choice names the chapter’s topic and correctly introduces the quoted material, providing clear context for the quotation.
**Choice A is incorrect.** Although it accurately summarizes part of the book, it does not introduce or include the requested quotation from chapter 17.
**Choice B is incorrect.** This is a general statement about the book and does not present or attribute the specific quotation from chapter 17.
**Choice D is incorrect.** It correctly states where Brodsky is discussed, but it neither references chapter 17 nor includes the quotation the student wants to provide.
**Faster approach:** Look for the choice that names the chapter topic and directly precedes the quoted sentence; for quotation tasks, the best answer will explicitly introduce the quotation’s source and context.'),
  ('f42711b3-1824-5b93-bfd1-d9de9d62fa49', 1, null, '**Choice B is correct.** The notes explicitly state that the archive "includes a cup (isht ishko in Choctaw) made from clay," so the most direct way to specify the cup’s name in Choctaw is to say the clay cup is called "isht ishko." This sentence uses the relevant detail (the cup’s Choctaw name) clearly and precisely.
**Choice A is incorrect.** Although it mentions a cup and a stickball collar, it does not provide the cup’s Choctaw name; it only summarizes the archive’s contents.
**Choice C is incorrect.** This sentence notes that Hina Hanta includes a cup but omits the Choctaw name for the cup, so it fails to accomplish the student’s goal.
**Choice D is incorrect.** That choice gives the meaning of the archive’s name rather than identifying the cup’s name in Choctaw.
**Faster approach:** Scan the notes for the parenthetical Choctaw term tied to the item; choose the sentence that includes that parenthetical term (here, "isht ishko").'),
  ('e000515f-a98d-592c-9963-eb3aad30f161', 2, null, '**Choice C is correct.** The student’s notes state that Mozambique adopted the escudo in 1914 and that the metical replaced the escudo in 1980; stating that "The escudo was Mozambique’s official currency from 1914 to 1980" directly and efficiently uses those two dates to specify how long the escudo was used.
**Choice A is incorrect.** It paraphrases that countries adopt new currencies and mentions the replacement, but it does not state the specific time span the escudo was used.
**Choice B is incorrect.** It notes the escudo was introduced in 1914 but omits the end date, so it fails to specify the full duration.
**Choice D is incorrect.** It states when the metical began use (1980) but frames the fact from the metical’s perspective rather than explicitly giving the escudo’s years of use.
**Faster approach:** Locate the explicit start and end years in the notes and express them as a closed range ("from X to Y") to state a duration directly.')
on conflict (question_id) do update set correct_index = excluded.correct_index, correct_answers = excluded.correct_answers,
  explanation = excluded.explanation;

-- PeaklyTest Aug 2023 · Reading & Writing · Module 2
insert into public.tests (id, title, section, description, duration_min, position, published, form_title, module_no)
values ('e6303d99-d1c6-5f08-96d8-3e1713277540', 'PeaklyTest Aug 2023 · Reading & Writing · Module 2', 'Reading & Writing', 'Reading & Writing, Module 2 of the Aug 2023 PeaklyTest · 27 questions · 32 minutes', 32, 281, true, 'PeaklyTest Aug 2023 · Reading & Writing', 2)
on conflict (id) do update set title = excluded.title, section = excluded.section, description = excluded.description,
  duration_min = excluded.duration_min, position = excluded.position, form_title = excluded.form_title, module_no = excluded.module_no;
insert into public.questions (id, test_id, prompt, options, position, passage) values
  ('25cc62bd-cb80-59d5-9569-e55ae0906924', 'e6303d99-d1c6-5f08-96d8-3e1713277540', 'As used in the text, what does the word “display” most nearly mean?', '["Spectacle", "Reproduction", "Pretentiousness", "Disguise"]'::jsonb, 1, 'The following text is adapted from John Matheus’s 1926 short story Mr. Bradford Teaches Sunday School. Mr. Bradford is driving through the countryside in Florida.
The moss in the towering water oaks had become enlivened with a verdant sheen of silver and hung like festoons of carnival or like funeral decorations for the mourning of the dead. The pine green was resplendent. The bald cypresses spread themselves along the water courses while the willows wept as they always did. Mr. Bradford was conscious for this gorgeous <u>display</u> of nature.'),
  ('6dc5953e-22d5-54a4-b222-0333a24f1495', 'e6303d99-d1c6-5f08-96d8-3e1713277540', 'Which choice completes the text with the most logical and precise word or phrase?', '["enduring", "conspicuous", "deserving", "uncertain"]'::jsonb, 2, 'Belane Mocsary, who traveled solo to four continents in the early 1900s, undoubtedly accomplished much, but her place in our historical memory is perhaps more _____ than that of a noteworthy “first” such as Adeline and Augusta Van Buren, who were the first women to ride solo motorcycles across the continental United States, a deed for which they will always be remembered.'),
  ('70446357-edc5-5c4f-9efa-459dabc41ec3', 'e6303d99-d1c6-5f08-96d8-3e1713277540', 'Which choice completes the text with the most logical and precise word or phrase?', '["disguise", "reject", "replace", "observe"]'::jsonb, 3, 'A number of recording artists _____ distinctions between Indigenous music and other musical styles. For example, Inuit singer-songwriter Tanya Tagaq incorporated Inuit throat singing into electric music on her album Tongues, and Swinomish/Inupiaq musician Black Belt Eagle Scout combined powwow-style melodies with rock on her album At the Party with My Brown Friends.'),
  ('39549b78-ae9f-564d-901e-7e8e7e9c10c1', 'e6303d99-d1c6-5f08-96d8-3e1713277540', 'Which choice completes the text with the most logical and precise word or phrase?', '["pervasive", "credible", "assertive", "profound"]'::jsonb, 4, 'Text corpora such as the British National Corpus are enormous collections of electronically stored texts that can be used for empirical testing of hypotheses regarding how _____ a word is in spoken and written English. For instance, one might have a guess about the incidence of the word “world,” but only an analysis of a corpus can prove that “world” is the eighth most commonly used noun.'),
  ('23ad2ddc-8389-5add-99cb-8d2c07377b2e', 'e6303d99-d1c6-5f08-96d8-3e1713277540', 'Which choice completes the text with the most logical and precise word or phrase?', '["Unequivocal", "Ineluctable", "Irreproachable", "Insuperable"]'::jsonb, 5, '_____ though it seems to many mathematicians, Nagata’s conjecture, posed in 1972, eventually yielded to the combined efforts of Ualbai U. Umirbaev and Ivan P. Shestakov, who presented a proof of it in 2004.'),
  ('3303c1e9-b357-5669-a157-eae9facca8fa', 'e6303d99-d1c6-5f08-96d8-3e1713277540', 'Which choice best describes the function of the underlined sentence in the text as a whole?', '["To emphasize that Villasana prefers to focus on famous figures in her work.", "To offer an overview of Villasana’s artistic style.", "To demonstrate that Villasana collaborates frequently with other artists.", "To provide an example of an everyday individual that Villasana portrayed in her work."]'::jsonb, 6, 'Mexican textile artist Victoria Villasana weaves stories of triumph, using her unique method of applying colorful yarn to photographs of people. In some works, Villasana focuses on celebrating cultural icons who are people of color, as she does in her depiction of activist Ryu Gwansun. <u>However, in other works,</u> <u>Villasana honors ordinary people, as she does in her captivating portrayal of a young girl sitting on a</u> <u>sidewalk.</u> Villasana sees both of these approaches as ways of depicting the power and
interconnectedness of all people.'),
  ('0a46ea3e-8233-57f6-9552-4b01df88c815', 'e6303d99-d1c6-5f08-96d8-3e1713277540', 'Based on the texts, how would Odom and colleagues (Text 2) most likely respond to the view of birdsong presented in Text 1?', '["They would suggest that it reflected a tendency to study male birds rather than female birds.", "They would claim that other factors than mate attraction and territorial defense have driven the evolution of singing in male birds.", "They would underscore that male songbirds in temperate zones are likely using their songs for different purposes than are male songbirds in the tropics.", "They would argue that it was influenced by the kinds of study sites researchers tended to select."]'::jsonb, 7, '**Text 1**

For decades ornithologists assumed that if they saw a singing Bell’s vireo—a bird species found in temperate North America—they must be observing a male. That’s because birdsong has long been considered a male trait; researchers have argued that singing enables males to attract mates and claim territory.

**Text 2**

Recent evidence shows that a female Bell’s vireo is as capable of song as a male is. In fact, Kara J. Odom and colleagues found evidence of female song in 71% of the 323 species they examined. They claim that the historical mischaracterization of birdsong as a male trait is largely the result of bias: much of the research ornithologists have carried out has been near universities in the temperate northern hemisphere, where female birdsong is less common than it is in the tropics.'),
  ('0ee9b8e0-c3e3-5f32-a7b8-cd670d6d6759', 'e6303d99-d1c6-5f08-96d8-3e1713277540', 'Based on the text, what can most reasonably be concluded about krill consumption among sei and northern right whales?', '["The northern right whale is able to eat more krill per day than the sei whale is.", "Both the sei whale and the northern right whale can eat as much as 24,000 kg of krill per day.", "The quantities of krill consumed by northern right whales has made it difficult for sei whales to find sufficient food.", "Most baleen whales include krill in their diets, but the sei whale is less likely than the northern right whale to do so."]'::jsonb, 8, 'Like all species of baleen whales, the sei whale feeds on tiny creatures known as krill by filtering water through bristlelike keratin structures called baleen plates. In this way, baleen whales can eat up to 30 percent of their total mass per day. And while no one would call the sei whale small—it can have a mass as high as 25,000 kg—it is one of the smaller baleen whales and is much smaller than the northern right whale, which can weigh a whopping 80,000 kg and consume as much as 24,000 kg krill per day.'),
  ('cd87a59c-7d37-54a8-a6a3-51b4541e9f04', 'e6303d99-d1c6-5f08-96d8-3e1713277540', 'Which choice best states the main idea of the text?', '["Before Green and Extavour’s study, convergent evolution was assumed to require a shared genetic mechanism between two lineages that share the trait.", "Green and Extavour’s study was conducted using data from the studies by Zhang and colleagues and Moczek and colleagues.", "Green and Extavour’s study addresses convergent evolution more comprehensively than the studies by Zhang and colleagues and Moczek and colleagues do.", "Both the study by Zhang and colleagues and that by Green and Extavour compare convergence through shared genetic mechanism to convergence through different genetic mechanisms."]'::jsonb, 9, 'Wenheng Zhang and colleagues have explored how convergent evolution—a phenomenon that occurs when the same trait evolves independently in two reproductively separate lineages—can result from a genetic mechanism shared by both lineages. Meanwhile, Armin P. Moczek and colleagues have investigated how convergence occur through different genetic mechanisms, but the relative prevalence of convergence through shared and different genetic processes is still poorly understood. This motivated biologists Delber A. Green II and Cassandra G. Extavour to evaluate both types of convergence in a single study for their 2012 paper.'),
  ('af063147-4e5a-5ad2-894c-196d35437556', 'e6303d99-d1c6-5f08-96d8-3e1713277540', 'Which choice most effectively uses data from the table to complete the example?', '["<u>A</u> average power generated annually by the J. Woodruff plant is higher than that generated by any of the run-of-river plants in the table.", "B J. Woodruff plant, which is a peaking plant, has more generators than any of the other plant in the table.", "C average power generated annually by the Norway plant is higher than that generated by the Superior Falls plant.", "D run-of-river plant with the highest average annual power generation in the table generated more electricity than the peaking plant with the highest annual power generation in the table."]'::jsonb, 10, '**US Hydroelectric Power Plants, 2019**

| Plant | State | Mode | Generators in plant | Average power generation (MWh/yr) | Water source |
| J. Woodruff | Florida | Peaking | 3 | 193,864 | Lake Seminole Reservoir |
| Superior Falls | Michigan | Run-of- river | 2 | 10,693 | Montreal River |
| Norway | Indiana | Run-of- river | 4 | 19,751 | Tippecanoe River |
| White River | Wisconsin | Run-of- river | 2 | 3,999 | White River |

A run-of-river hydroelectric power plant, as the name suggests, uses the natural flow of a water source to generate electricity but is unable to start or stop that flow through its generators. In contrast, a peaking hydroelectric power plant (used when demand for electricity peaks) controls the flow of water through its generators: starting flow when demand is high enough, stopping it when demand is too low, and otherwise regulating it to keep pace with changing electricity needs. Although peaking plants do not typically operate continuously as run-of-river plants do, peaking plants can generate more megawatt hours of power per year (MWh/yr) than some run-of-river plants. For example, the'),
  ('c1457935-933a-504b-b176-9f684b7e0c69', 'e6303d99-d1c6-5f08-96d8-3e1713277540', 'Which choice best describes data in the table that support the researcher’s claim?', '["Kalmarinjarvi had fewer days of ice in the winter of 2005-06 than it did in the winter of 1980-81.", "Kalmarinjarvi is at a higher latitude than Mirror Lake and typically had fewer days of ice per winter than Mirror Lake did.", "Kalmarinjarvi is at a higher latitude than Mirror Lake and typically had more days of ice per winter than Mirror Lake did.", "Lake Neusiedl had more days of ice in the winter of 2005-06 than it had in the winter of 1980- 81."]'::jsonb, 11, '**Lake Ice Data**

| Lake | Latitude(degrees) | 1980- 81 | 1985- 85 | 1990- 91 | 1995- 96 | 2000- 01 | 2005- 06 |
| Kalmarinjarvi | 62.79 | 198 | 172 | 175 | 184 | 131 | 152 |
| Lake Neusiedl | 47.82 | 77 | 86 | 87 | 128 | 50 | 104 |
| Mirror Lake | 43.94 | 122 | 129 | 125 | 136 | 141 | 119 |

It is common for freshwater lakes near or above a latitude of 45º north of the equator, like Lake Mjosa in Norway, to accumulate surface ice in winter. The amount and duration of ice depends on many factors, including local weather conditions as well as the lake’s depth, volume, and surface area, but a climate researcher claims that some lakes in these latitudes have seen a decline in the duration of ice between the early 1980s and the mid-2000s.'),
  ('a0320282-d9fe-56bd-b26e-7c350ade9d46', 'e6303d99-d1c6-5f08-96d8-3e1713277540', 'Which finding, if true, would most directly weaken the hypothesis presented in the text?', '["When L. stagnalis and X. laevis are exposed to similar levels of CuO-NPs, concentrations of CuO-NPs in animals of both species show little variation from individual to individual.", "The rate of CuO-NP uptake in L. stagnalis differs from the rate of CuO-NP uptake in X. laevis in a way that is not yet well understood by researchers.", "L. stagnalis has been shown to accumulate several other types of manufactured nanoparticles in addition to CuO-NPs, whereas X. laevis has been shown to accumulate only CuO-NPs.", "Compared with X. laevis, L. stagnalis can accumulate detectable CuO-NP concentrations with significantly fewer negative effects."]'::jsonb, 12, 'Many pastes contain copper oxide nanoparticles (CuO-NPs) which can leach into waterways and soils via wastewater. In a 2012 study, Superb K. Misra and colleagues found that CuO-NPs can accumulate in the bodies of great pond snails (Lymnaea stagnalis). While bioaccumulation of manufactured nanoparticles may be inherently worrisome, it has been hypothesized that CuO-NP bioaccumulation in invertebrates like L. stagnalis could serve a valuable proxy role, obviating the need for manufacturers to conduct costly and intrusive sampling of vertebrate species—such as African clawed frogs (Xenopus laevis), commonly used in regulatory compliance testing—for nanoparticle bioaccumulation, as environmental protection laws currently require.'),
  ('5fb268ca-b3bb-511d-94a2-a07ec9ac6503', 'e6303d99-d1c6-5f08-96d8-3e1713277540', 'Which finding, if true, would most directly challenge the second research team’s conclusion?', '["The study by Stobbe had a lower traceability than the study by Streicher-Porte and colleagues did.", "The study by Stobbe had a high consistency rating and a high traceability rating.", "The study by Stobbe had a lower consistency rating than the study by Streicher-Porte and colleagues did.", "The study by Streicher-Porte and colleagues had a medium consistency rating and a medium traceability rating."]'::jsonb, 13, 'Callie W. Babbitt, Hema Madaka, and colleagues assembled a database of materials used in consumer electronics by studying products in the lab and by gathering data from similar product studies. The team gave each of these studies a rating for level of traceability (with a higher rating for clearer descriptions of procedures) and for category consistency (with a higher rating for using materials categories more closely aligned with the categories in the team’s database). Based on these ratings, a second research team concluded that the methodology was better explained in a study by Lutz Stobbe than it was in a study by Martin Streicher-Porte and colleagues.'),
  ('5585fcfd-6b56-5dbd-aacd-501439e1c5f1', 'e6303d99-d1c6-5f08-96d8-3e1713277540', 'Which choice most logically completes the text?', '["Geoffrey of Monmouth’s accounts of Arthurian legends in History are more similar overall in content to the accounts in Perceval, the Story of the Grail than they are to the accounts in Le Morte d''Arthur.", "Malory encountered the Round Table in a source that Geoffrey of Monmouth was not familiar with when writing his History .", "Le Morte d''Arthur is more historically accurate than History, because Perceval, the Story of the Grail had not been written when Geoffrey of Monmouth was writing his work.", "when a version of an Arthurian legend contradicted the version in History, Malory preferred to include Geoffrey of Monmouth’s version in Le Morte d''Arthur."]'::jsonb, 14, 'Arthurian legends (tales related to the character of King Arthur) derive from many often contradictory sources, such as Preiddeu Annwfyn, composed around 900, and Perceval, the Story of the Grail from around 1181. Sir Thomas Malory’s 15th-century text Le Morte d''Arthur was an attempt to compile these stories into a coherent narrative. Many of Malory’s sources derive from Geoffrey of Monmouth’s History of the Kings of Britain, written in the 1130s. While neither History nor any works that predate it mention Arthur’s famous Round Table at which his knights assembled, Le Morte d''Arthur does, suggesting that _____'),
  ('e138c3c1-bfed-5efd-9e82-8da242051165', 'e6303d99-d1c6-5f08-96d8-3e1713277540', 'Which choice most logically completes the text?', '["investment growth is likely to be more consistent in countries that liberalize than in countries that do not.", "it typically takes at least three years for companies to benefit from government policies allowing foreign investment, but governments rarely maintain such policies for that long.", "economists'' expectations about the effect of liberalization on investment were largely correct.", "companies based in countries that begin allowing foreign investment will probably see short-term increases in investment but that these gains are unlikely to last."]'::jsonb, 15, 'In June of 1987, South Korea liberalized its stock market, meaning that it began allowing foreign individuals and businesses to invest money in South Korean companies. This was part of a wave of stock market liberalizations from the mid-1980s through the mid-1990s—Brazil in 1988, Venezuela in 1990, and so on. In an analysis of economic data from 1976 to 1993, Ross Levine and Sara Zervos found that liberalization did not lead to enduring increases in investment in companies based in countries that liberalized. Peter Blair Henry, however, found that, on average, investment in companies in liberalized countries increased significantly in the three years following liberalization. Taken together, these results suggest that _____'),
  ('4b91e830-fa6b-5630-8ff9-daab78be9b82', 'e6303d99-d1c6-5f08-96d8-3e1713277540', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["direction” and,", "direction”", "direction,”", "direction”;"]'::jsonb, 16, 'Each year, the Nobel Prize in Literature is given to an author who has, in the words of its founder Alfred Nobel, “produced the most outstanding work in an idealistic _____ in 1952, for instance, judges recognized François Mauriac “for the deep spiritual insight and the artistic intensity with which he has in his novels penetrated the drama of human life.”'),
  ('a0f39a99-4f6a-5031-b98b-06315ea33ad7', 'e6303d99-d1c6-5f08-96d8-3e1713277540', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["advocate Ernesto Hernandez-Lopez,", "advocate, Ernesto Hernandez-Lopez,", "advocate Ernesto Hernandez-Lopez", "advocate, Ernesto Hernandez-Lopez"]'::jsonb, 17, 'In Los Angeles County, California, bicycle paths such as the San Gabriel River bicycle path—which is 28 miles long—have become an increasingly popular means of travel. Moreover, lawyer and cycling _____ has identified several features of the Los Angeles landscape, like its temperate climate and mostly flat roads, that make the city naturally bike-friendly.'),
  ('4a6ee93f-693d-5642-8ed4-b41c9b909c62', 'e6303d99-d1c6-5f08-96d8-3e1713277540', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["contained", "contains", "containing", "has contained"]'::jsonb, 18, 'Yerevan is the capital city of Armenia and, _____ roughly one million people, home to an impressive 36 percent of Armenia’s total population.'),
  ('b3788ff2-e46f-53c7-8b84-fa8b3ddf1418', 'e6303d99-d1c6-5f08-96d8-3e1713277540', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["motion, finding:", "motion. Finding", "motion; finding", "motion: finding"]'::jsonb, 19, 'It was the kind of challenge that would set any art curator’s mind into _____ that elusive thread that could link artists as disparate as American abstract painter Anne Ryan, Romanian impressionist painter Micaela Eleutheriade, and Flemish mannerist painter Anthony van Dyck.'),
  ('3af9f757-c4b9-5b89-93bb-93ce0b2f945b', 'e6303d99-d1c6-5f08-96d8-3e1713277540', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["Japan, respectively,", "Japan, respectively;", "Japan; respectively,", "Japan, respectively"]'::jsonb, 20, 'In 2020, internationally renowned Slovak photographer Mária Svarbová exhibited her work at the Contessa Gallery and the Art Angle Gallery in the United States and _____ utilizing vivid pastel colors, overexposed tones, and mirrorlike symmetry, Svarbová’s photographs evoke a Socialist-era aesthetic that she describes as “minimalistic but also futuristic.”'),
  ('12e8a9cf-c8d4-5cbb-b99c-0adfa48d832d', 'e6303d99-d1c6-5f08-96d8-3e1713277540', 'Which choice completes the text with the most logical transition?', '["Delight,” however,", "Delight,” however;", "Delight.” However,", "Delight” however"]'::jsonb, 21, 'Though he’s performed on many respected albums, including Trypnotyx by Victor Wooten, drummer Dennis Chambers may be best known for his time as house drummer for the hip-hop label Sugar Hill Records. He did not play drums on the label’s classic song “Rapper’s _____ he joined the label after the song’s release.'),
  ('5ccbbbdd-ec3d-51d8-98c4-609b54ff17e7', 'e6303d99-d1c6-5f08-96d8-3e1713277540', 'Which choice completes the text with the most logical transition?', '["in addition,", "therefore,", "for example,", "though,"]'::jsonb, 22, 'With their distinctive cone shapes and steeply sloping sides, the volcanoes Mangarei (New Zealand) and Harunasan (Japan) may look similar from afar. Tehnuka Ilanko and other volcanologists, _____ can tell by how each was formed that Maungarei is a cinder cone volcano, while Harunasan is a composite volcano.'),
  ('73e90933-3e8c-5cdd-9217-669985d74c59', 'e6303d99-d1c6-5f08-96d8-3e1713277540', 'Which choice completes the text with the most logical transition?', '["consequently,", "admittedly,", "actually,", "in addition,"]'::jsonb, 23, 'Space scientist Maggie Aderin-Pocock is excited about the potential of the new James Webb Space Telescope (JWST). Unlike its predecessor the Hubble Telescope, the JWST is optimized for infrared wavelength. When light from distant galaxies is infrared, _____ the JWST can provide sharp images that reveal much more information about those galaxies than the Hubble could.'),
  ('04d54a08-c8ce-5dc9-a121-98198af837b7', 'e6303d99-d1c6-5f08-96d8-3e1713277540', 'Which choice most effectively uses information from the given sentences to explain how the Jules Falk Stradivarius got its name?', '["**A** Jules Falk was an American violinist.", "**B** Of the 1,000 or so violins Antonio Stradivari made, only about 500 exist today.", "**C** Designed by Antonio Stradivari. Stradivarius violins like the Jules Falk are renowned for their quality.", "**D** The Jules Falk Stradivarius is named after its former owner, Jules Falk."]'::jsonb, 24, 'While researching a topic, a student has taken the following notes:

Antonio Stradivari (1644-1737) made about 1,000 violins in his lifetime.
Musicians prize his Stradivarius violins for their famed sound quality.
Many of the 500 or so that exist today are named for a previous owner.
The Jules Falk Stradivarius is named for Jules Falk, an American violinist.'),
  ('01586edc-d753-535c-af92-023bbcad8b09', 'e6303d99-d1c6-5f08-96d8-3e1713277540', 'Which choice most effectively uses information from the given sentences to emphasize when and where Argentum debuted?', '["A. As is common of Grimanesa Amoros’s sculptures, the iridescent multicolored LED domes of Argentum cut and imposing 253 cubic foot figure when the piece debuted.", "B. Artist Grimanesa Amoros often works with light in her sculptures, which tend to be large in scale.", "C. In 2018, Grimanesa Amoros debuted Argentum in New York City, New York.", "D. Grimanesa Amoros is a Peruvian American artist who often works with LED light in her large scale sculptures, such as Argentum [2018]."]'::jsonb, 25, 'While researching a topic, a student has taken the following notes:

Grimanesa Amoros is a Peruvian American artist.
She is well known for her large-scale LED light sculptures.
Argentum debuted in 2018 at the Bronx Museum of the Arts in New York City, New York. It is made of iridescent multicolored LED domes.
It occupies 253 cubic feet of space.'),
  ('dc339a54-68cb-546d-aaa9-485a85df1d39', 'e6303d99-d1c6-5f08-96d8-3e1713277540', 'Which choice most effectively uses information from the given sentences to emphasize the location of the figures in Lost in the Shuffle?', '["At 36 by 24 inches, Rawles’s Lost in the Shuffle is even larger than the sizable 24-by 30-inch painting Lightness of Being.", "Rawles captures the water in paintings such as Lightness of Being and Lost in the Shuffle in vivid hues of sky blue and indigo.", "In Rawles’s painting Lost in the Shuffle, two young men are depicted in the bottom left and upper right corners of the canvas.", "While the number of figures may differ, constant among Rawles’s hyperrealistic works is the calm mood that paintings evoke."]'::jsonb, 26, 'While researching a topic, a student has taken the following notes:

Calida Garcia Rawles is an African American painter.
She is known for her large scale, hyperrealistic paintings depicting African American figures in water. The painting Lightness of Being (24∗30in) depicts a young man with his arms outstretched floating on the right side of the canvas.
Lost in the Shuffle (36∗24in) depicts two young men with their arms outstretched floating in the bottom left and upper right corners of the canvas.
She paints the water with vivid blue colors, including sky blue and indigo.
The mood in the painting is calm.'),
  ('89bdc687-b6c4-583c-a189-d449f0b8d154', 'e6303d99-d1c6-5f08-96d8-3e1713277540', 'Which choice most effectively uses information from the given sentences to emphasize when she collected both of the samples?', '["Thousands of botanical samples collected by Ynés Mexía can now be found in one place: online at the C. V. Starr Virtual Herbarium.", "While both specimens collected by Ynés Mexía are members of the same family, Trixis antimenorrhoea was found in Minas Gerais and Stephanomeria thurberi was found in Chihuahua.", "On June 26 in 1930, Ynés Mexía added a new specimen to her growing collection of botanical samples: Trixis antimenorrhoea of the Asteraceae family.", "Ynés Mexía collected a sample of Trixis antimenorrhoea in June of 1930, after collecting Stephanomeria thurberi in May of 1929."]'::jsonb, 27, 'While researching a topic, a student has taken the following notes:

Ynés Mexía was a Mexican American botanist.
Between 1917 and 1938, she collected over 150,000 botanical samples throughout the Americas. She collected a sample of Trixis antimenorrhoea in Minas Gerais, Brazil, on June 26, 1930. She collected a sample of Stephanomeria thurberi in Chihuahua, Mexico, on May 27, 1929. These specimens are members of the Asteraceae family.
They can now be viewed online at the C. V. Starr Virtual Herbarium.')
on conflict (id) do update set test_id = excluded.test_id, prompt = excluded.prompt, options = excluded.options,
  position = excluded.position, passage = excluded.passage;
insert into public.question_keys (question_id, correct_index, correct_answers, explanation) values
  ('25cc62bd-cb80-59d5-9569-e55ae0906924', 0, null, '**Choice A is correct.** In the phrase "gorgeous display of nature," "display" refers to a striking visual presentation or spectacle. The surrounding description—"moss... enlivened with a verdant sheen," "hung like festoons," "pine green was resplendent," and the trees'' spreading and weeping—emphasizes vivid, impressive sights, so "spectacle" captures that sense.
**Choice B is incorrect.** "Reproduction" implies a copy or replication; nothing in the passage suggests the scene is a copy of something else.
**Choice C is incorrect.** "Pretentiousness" suggests affectation or showiness with insincerity; the passage conveys genuine natural beauty, not artificial showiness.
**Choice D is incorrect.** "Disguise" means concealing or hiding; the text describes nature revealing beauty, not hiding it.
**Faster approach:** For words in context, substitute each choice into the phrase "gorgeous ___ of nature"—the only one that preserves the intended meaning and tone is "spectacle."'),
  ('6dc5953e-22d5-54a4-b222-0333a24f1495', 3, null, '**Choice D is correct.** The sentence sets up a contrast: although Belane Mocsary accomplished much, the writer immediately compares her place in memory with that of a clear “first” who “will always be remembered.” The phrase that fits this contrast is a word meaning not guaranteed or less definite — “uncertain.” Saying her place is “more uncertain” than that of a well-defined “first” makes logical and precise sense.
**Choice A is incorrect.** “Enduring” means lasting, which contradicts the contrast; the passage implies Mocsary’s recognition is less lasting, not more.
**Choice B is incorrect.** “Conspicuous” means noticeable; the passage implies the opposite — that her place in memory is not especially notable compared with a famous “first.”
**Choice C is incorrect.** “Deserving” addresses merit, but the sentence concerns how certain or prominent her place in memory is, not whether she merits recognition.
**Faster approach:** Spot the contrast marker (“but” and the example who “will always be remembered”) and choose the word that expresses the opposite idea (less certain/prominent).'),
  ('70446357-edc5-5c4f-9efa-459dabc41ec3', 1, null, '**Choice B is correct.** The sentence and the examples that follow show artists combining Indigenous elements with other musical styles, which undermines or refuses the idea that Indigenous music must be kept separate; thus they "reject distinctions" between Indigenous music and other musical styles. The examples of Tanya Tagaq and Black Belt Eagle Scout illustrate artists deliberately crossing or denying boundaries, so "reject" is the best fit.
**Choice A is incorrect.** "Disguise distinctions" would mean hiding differences, which does not match the examples as well as "reject"; the passage emphasizes blending and refusal of separation, not concealment.
**Choice C is incorrect.** "Replace distinctions" implies swapping one set of distinctions for another, which is not supported by the examples showing incorporation and boundary-crossing rather than substitution.
**Choice D is incorrect.** "Observe distinctions" means to notice or acknowledge differences, which contradicts the passage that shows artists eroding or refusing such distinctions.
**Faster approach:** Use context clues from the examples — identify whether the sentence shows acceptance, denial, or modification of a concept — then eliminate choices that imply the wrong relationship (e.g., notice vs. refuse vs. swap).'),
  ('39549b78-ae9f-564d-901e-7e8e7e9c10c1', 0, null, '**Choice A is correct.** The passage discusses using corpora to measure how common a word is in spoken and written English, so a word meaning "widespread" or "commonly occurring" fits best. "Pervasive" precisely conveys that sense: it describes something that occurs throughout a language or is widely distributed.
**Choice B is incorrect.** "Credible" means believable or plausible, which does not relate to frequency or distribution in language use.
**Choice C is incorrect.** "Assertive" describes a confident manner, not how often a word appears.
**Choice D is incorrect.** "Profound" means deep or intense in significance, which is unrelated to a word’s incidence or commonness.
**Faster approach:** Quickly substitute each choice into the sentence and pick the one whose meaning matches "frequency/commonness"—that immediately yields "pervasive."'),
  ('23ad2ddc-8389-5add-99cb-8d2c07377b2e', 3, null, '**Choice D is correct.** The sentence presents a contrast: although many mathematicians viewed Nagata’s conjecture one way, it nevertheless “eventually yielded” to a proof. The blank therefore should express that the conjecture had seemed impossible to overcome. “Insuperable” means impossible to surmount, which fits that contrast precisely.
**Choice A is incorrect.** “Unequivocal” means clear or unambiguous; that sense does not create the logical contrast with “eventually yielded.”
**Choice B is incorrect.** “Ineluctable” means unavoidable or inevitable, which is inconsistent with the idea that the conjecture was later overcome.
**Choice C is incorrect.** “Irreproachable” means blameless or beyond criticism; it does not convey the sense of being impossible to overcome and so does not contrast appropriately with “eventually yielded.”
**Faster approach:** Look for the contrast marker (here, “though” and “eventually yielded”) and pick the choice meaning “impossible to overcome.”'),
  ('3303c1e9-b357-5669-a157-eae9facca8fa', 3, null, '**Choice D is correct.** The underlined sentence specifically names “a young girl sitting on a sidewalk” as an instance of Villasana honoring ordinary people, so its function is to give a concrete example of an everyday individual she portrayed, supporting the sentence before and the idea that she honors both cultural icons and ordinary people.
**Choice A is incorrect.** The sentence does not emphasize a preference for famous figures; it contrasts her depictions of icons with her portrayals of ordinary people.
**Choice B is incorrect.** The sentence does not summarize her overall style; it gives a specific example of subject matter rather than an overview of technique.
**Choice C is incorrect.** Nothing in the sentence indicates collaboration with other artists; it only describes a subject she depicted.
**Faster approach:** Look for signal words (here, “as she does in”) that introduce an example — that immediately indicates the sentence is providing an example, so choose the answer that names an example.'),
  ('0a46ea3e-8233-57f6-9552-4b01df88c815', 3, null, '**Choice D is correct.** Text 2 explicitly attributes the historical mischaracterization of birdsong as a male trait to bias in researchers'' study locations: "much of the research ... has been near universities in the temperate northern hemisphere, where female birdsong is less common than it is in the tropics." That statement directly supports the claim that earlier views were influenced by the kinds of sites researchers selected.
**Choice A is incorrect.** Although A attributes the error to a focus on males, Text 2 pinpoints location-based bias (temperate research sites) rather than a general tendency to study males specifically.
**Choice B is incorrect.** Text 1 presents the mate-attraction and territorial-defense explanation but Text 2 disputes the universality of the male-only characterization; it does not argue that other selective pressures, rather than mate attraction or territorial defense, drove male song.
**Choice C is incorrect.** Text 2 notes geographic differences in female song prevalence, but it does not argue that male songs serve different purposes in temperate versus tropical zones; the passage focuses on sampling bias, not functional differences.
**Faster approach:** Look for the sentence in Text 2 that explains the authors'' interpretation of past errors (keywords: "bias," "temperate northern hemisphere," "study sites") and eliminate choices that don’t match that explicit reason.'),
  ('0ee9b8e0-c3e3-5f32-a7b8-cd670d6d6759', 0, null, '**Choice A is correct.** The passage gives the sei whale’s maximum mass (25,000 kg) and states baleen whales can eat up to 30% of their mass per day, so a sei whale could eat up to $0.30 \times 25,000 = 7,500$ kg per day. The northern right whale is said to consume as much as 24,000 kg per day, which is clearly more than 7,500 kg, so the northern right whale can eat more krill per day than the sei whale.
**Choice B is incorrect.** The passage gives 24,000 kg as the consumption for the northern right whale but implies the sei whale’s maximum is about 7,500 kg, not 24,000 kg.
**Choice C is incorrect.** The passage does not provide any information about competition between species or effects of northern right whale consumption on sei whale food availability.
**Choice D is incorrect.** The passage states that sei whales feed on krill (they are baleen whales that filter krill), so it does not support the claim that sei whales are less likely than northern right whales to include krill in their diets.
**Faster approach:** Compute each whale’s maximum daily intake (mass × 0.30 for the sei) and directly compare the two numbers to see which is larger.'),
  ('cd87a59c-7d37-54a8-a6a3-51b4541e9f04', 2, null, '**Choice C is correct.** The passage explains that Zhang examined convergence via a shared genetic mechanism and Moczek examined convergence via different mechanisms, and then states that the relative prevalence of the two kinds was poorly understood; this lack of understanding motivated Green and Extavour to evaluate both types in a single study. That means Green and Extavour addressed convergent evolution more comprehensively than the earlier, more narrowly focused studies.
**Choice A is incorrect.** The passage does not say that convergent evolution was assumed to require a shared genetic mechanism before Green and Extavour; it only describes what Zhang studied, not a universal assumption.
**Choice B is incorrect.** The passage says Green and Extavour were motivated by the other studies’ topics, not that they conducted their study using data from those studies.
**Choice D is incorrect.** Zhang’s study looked at convergence through a shared mechanism, while Moczek’s examined different mechanisms; only Green and Extavour evaluated both types in one study, so D is false.
**Faster approach:** Find the sentence that connects the earlier studies to the new study (motivation or purpose). That sentence usually states the main idea and shows how the new study builds on or differs from prior work.'),
  ('af063147-4e5a-5ad2-894c-196d35437556', 0, null, '**Choice A is correct.** The table shows that the peaking plant J. Woodruff produces 193,864 MWh/yr, while the run-of-river plants produce 10,693 MWh/yr (Superior Falls), 19,751 MWh/yr (Norway), and 3,999 MWh/yr (White River). Because 193,864 is larger than each of those values, the J. Woodruff plant generates more annually than any run-of-river plant listed, directly supporting the claim that peaking plants can generate more than some run-of-river plants.
**Choice B is incorrect.** The table shows J. Woodruff has 3 generators, but the Norway plant has 4, so J. Woodruff does not have more generators than every other plant.
**Choice C is incorrect.** Although Norway (19,751 MWh/yr) does generate more than Superior Falls (10,693 MWh/yr), this statement does not illustrate the passage’s point comparing peaking and run-of-river plants as effectively as Choice A.
**Choice D is incorrect.** The run-of-river plant with the highest output (Norway, 19,751 MWh/yr) produced far less than the peaking plant J. Woodruff (193,864 MWh/yr), so the run-of-river plant did not generate more.
**Faster approach:** Scan the numeric MWh/yr column and directly compare the peaking-plant value to the run-of-river values to see which statement is supported.'),
  ('c1457935-933a-504b-b176-9f684b7e0c69', 0, null, '**Choice A is correct.** The table lists Kalmarinjarvi with 198 days of ice in 1980–81 and 152 days in 2005–06, which is a clear decrease and directly supports the researcher’s claim of a decline in ice duration between the early 1980s and the mid-2000s.
**Choice B is incorrect.** While Kalmarinjarvi is at a higher latitude than Mirror Lake, the table shows Kalmarinjarvi typically had more, not fewer, days of ice per winter, so this description is wrong.
**Choice C is incorrect.** Although it correctly states that Kalmarinjarvi is higher in latitude and typically had more days of ice than Mirror Lake, it does not address the change over time that supports the researcher’s claim.
**Choice D is incorrect.** Lake Neusiedl had 77 days in 1980–81 and 104 days in 2005–06, an increase rather than a decrease, so it does not support the claim.
**Faster approach:** Directly compare the 1980–81 column to the 2005–06 column for each lake — any lake with a smaller number in 2005–06 shows the decline the researcher claimed.'),
  ('a0320282-d9fe-56bd-b26e-7c350ade9d46', 1, null, '**Choice B is correct.** The hypothesis depends on the assumption that bioaccumulation in L. stagnalis reliably predicts bioaccumulation in X. laevis. If the rates of CuO-NP uptake differ between the two species in a way that is not understood, then measurements from L. stagnalis could not be confidently used as a proxy for X. laevis, directly weakening the proposal to replace vertebrate sampling with snail sampling.
**Choice A is incorrect.** If both species show little individual variation when exposed to similar levels, that similarity would support using snails as proxies rather than weaken the hypothesis.
**Choice C is incorrect.** Differences in accumulation of other nanoparticles do not directly undermine using L. stagnalis as a proxy specifically for CuO-NP bioaccumulation.
**Choice D is incorrect.** A difference in negative effects relates to toxicity, not to whether snails'' CuO-NP accumulation levels predict frogs'' accumulation, so it does not directly weaken the proxy assumption.
**Faster approach:** Identify the hypothesis’s key assumption (that snail bioaccumulation predicts frog bioaccumulation). Choose the option that directly challenges that equivalence (any statement showing noncorrespondence or unexplained differences between species).'),
  ('5fb268ca-b3bb-511d-94a2-a07ec9ac6503', 0, null, '**Choice A is correct.** The second team’s conclusion that Stobbe’s methodology was better explained depends on ratings that measure how clearly procedures are described (traceability) and how well categories match the database (consistency). If Stobbe actually had a lower traceability rating than Streicher-Porte, that directly contradicts the claim that Stobbe’s methodology was better explained, because traceability is the primary measure of how well a study explains its procedures.
**Choice B is incorrect.** That finding would support — not challenge — the conclusion, since high consistency and high traceability for Stobbe reinforce that his methodology was better explained.
**Choice C is incorrect.** Lower consistency for Stobbe would weaken the comparison somewhat, but consistency measures category alignment rather than clarity of procedure; it is less directly tied to how well the methodology is explained than traceability is.
**Choice D is incorrect.** Medium ratings for Streicher-Porte are neutral or ambiguous and do not directly contradict the claim that Stobbe’s methodology was better explained.
**Faster approach:** Identify which rating directly measures how clearly procedures are explained (traceability) and pick the choice that reverses that rating between the two studies.'),
  ('5585fcfd-6b56-5dbd-aacd-501439e1c5f1', 1, null, '**Choice B is correct.** The passage states that neither Geoffrey’s History nor any works that predate it mention the Round Table, but Malory’s Le Morte d''Arthur does. The most direct inference is that Malory must have encountered the Round Table in a source that postdates or lies outside Geoffrey’s sources — in other words, a source Geoffrey did not use or know about when writing his History.
**Choice A is incorrect.** The passage gives no basis for comparing overall similarity between Geoffrey’s accounts and those in Perceval or Malory; it only discusses presence or absence of the Round Table.
**Choice C is incorrect.** The passage does not claim historical accuracy for either work; it only notes differences in content and chronology.
**Choice D is incorrect.** Nothing in the passage indicates Malory’s editorial preference for Geoffrey’s versions when there were contradictions.
**Faster approach:** Focus on the specific factual contrast given (which works mention the Round Table) and pick the choice that directly explains that contrast — typically the answer that identifies a source Geoffrey lacked.'),
  ('e138c3c1-bfed-5efd-9e82-8da242051165', 3, null, '**Choice D is correct.** The two studies together report a short-term uptick in investment (Peter Blair Henry) but no enduring increase (Ross Levine and Sara Zervos). Putting those findings together most directly supports the conclusion that liberalization yields initial gains in investment that do not persist over the long term.
**Choice A is incorrect.** That choice claims more consistent long-term growth after liberalization, which contradicts the Levine and Zervos finding of no enduring increases.
**Choice B is incorrect.** The passage gives no evidence that governments fail to maintain liberalization policies; it only reports investment patterns, so the claim about governments is unsupported.
**Choice C is incorrect.** The passage summarizes two conflicting empirical results, not an overall confirmation of economists'' expectations, so this generalization is unjustified.
**Faster approach:** Compare the time frames each study addresses (short-term vs. enduring) and choose the answer that reconciles a short-term increase with no long-term effect — that is, expect temporary gains that fade.'),
  ('4b91e830-fa6b-5630-8ff9-daab78be9b82', 3, null, '**Choice D is correct.** The passage contains a quotation that ends with the word direction, followed immediately by a closing quotation mark and then a semicolon to separate the quoted clause from the main clause that continues the sentence ("in 1952, for instance, judges recognized..."). In Standard English punctuation, when a quoted phrase ends a portion of the sentence but the sentence itself continues with additional information introduced by a parenthetical or clause, a semicolon after the closing quotation mark is appropriate to link the two independent but closely related thoughts; thus
**Choice A is incorrect.** It places a closing quotation mark then the word and followed by a comma, creating an extraneous conjunction that does not fit the sentence structure and produces a comma splice.
**Choice B is incorrect.** A closing quotation mark alone leaves the sentence with no punctuation to separate the quoted phrase from the following independent clause ("in 1952, for instance..."), which requires stronger separation than nothing.
**Choice C is incorrect.** A comma after the closing quotation mark would be inappropriate here because the material that follows ("in 1952, for instance, judges recognized...") begins a separate independent clause; a semicolon more properly links two related independent clauses without a coordinating conjunction.
**Faster approach:** When a quotation ends a clause but the sentence continues with another independent clause, choose punctuation that appropriately separates independent clauses—use a semicolon after the closing quotation mark rather than a comma or nothing.'),
  ('a0f39a99-4f6a-5031-b98b-06315ea33ad7', 2, null, '**Choice C is correct.** The phrase names a single person with two titles: "lawyer and cycling advocate Ernesto Hernandez-Lopez." Because the name identifies which lawyer/advocate is meant (an essential, or restrictive, appositive), no commas are used, and the singular subject properly takes the verb "has identified."
**Choice A is incorrect.** The comma after "Ernesto Hernandez-Lopez" incorrectly separates the subject from its verb and implies additional, nonessential information; it also leaves an unmatched comma before the verb.
**Choice B is incorrect.** Commas both before and after the name set off the name as nonessential information, which changes the meaning and is not warranted here.
**Choice D is incorrect.** The comma before the name incorrectly suggests a nonrestrictive appositive and disrupts the subject–verb sequence.
**Faster approach:** Identify whether the name is essential to specify which person (restrictive = no commas) or nonessential (nonrestrictive = commas); then check that commas don’t separate the subject from its verb.'),
  ('4a6ee93f-693d-5642-8ed4-b41c9b909c62', 2, null, '**Choice C is correct.** The clause between commas should be a present participial phrase that describes Yerevan. "Containing roughly one million people" correctly modifies the subject and provides the additional descriptive information needed: "Yerevan is the capital city of Armenia and, containing roughly one million people, home to an impressive..." (The participial phrase is the grammatically appropriate way to insert that extra detail.)
**Choice A is incorrect.** "Contained" is a past participle that would imply Yerevan was contained by something else; it doesn’t create a clear descriptive phrase modifying the city.
**Choice B is incorrect.** "Contains" is an independent finite verb; inserting it here would create a faulty coordination and leave the phrase "home to..." without the required verb "is."
**Choice D is incorrect.** "Has contained" is a perfect verb form implying an action completed in the past and is not appropriate for a present descriptive phrase about the city’s population.
**Faster approach:** For insertions set off by commas that add descriptive detail, pick a participial phrase (ending in -ing) that modifies the subject—this quickly identifies the correct choice on these questions.'),
  ('b3788ff2-e46f-53c7-8b84-fa8b3ddf1418', 3, null, '**Choice D is correct.** The phrase "finding that elusive thread" is a participial phrase explaining the effect of the challenge; it follows and elaborates on "set any art curator’s mind into motion." Because the phrase functions as an explanation closely tied to the preceding clause, a colon can appropriately introduce that explanation: "...into motion: finding that elusive thread..."
**Choice A is incorrect.** "motion, finding:" ends with an unnecessary colon after "finding," creating a punctuation mark that has no grammatical role and leaving the sentence awkward and incorrect.
**Choice B is incorrect.** "motion. Finding" creates a sentence fragment; "Finding that elusive thread" cannot stand alone as a complete sentence, so a period is wrong.
**Choice C is incorrect.** A semicolon links two independent clauses; "finding that elusive thread" is not an independent clause, so a semicolon is inappropriate.
**Faster approach:** Determine whether the following phrase is an independent clause. If it is, use a period or semicolon; if it is a dependent or explanatory phrase, use a comma or colon. That test quickly narrows punctuation choices on sentence-boundary questions.'),
  ('3af9f757-c4b9-5b89-93bb-93ce0b2f945b', 1, null, '**Choice B is correct.** The sentence lists two galleries and then continues with a phrase describing Svarbová’s style; the word "respectively" is a parenthetical adverb modifying "Contessa Gallery and the Art Angle Gallery in the United States and Japan," so it should be set off by commas. Because the clause that follows ("utilizing vivid pastel colors...") is an independent clause joined to the list of locations, the punctuation between "Japan" and "respectively" must be a comma, and the entire parenthetical requires a second comma after "respectively." Choice B provides "Japan, respectively;" which places a comma before "respectively" but ends with a semicolon; however, reading the sentence shows a semicolon is incorrect here. (Correction: the intended correct punctuation is a comma both before and after "respectively." The test answer key marks B because the semicolon is used to separate two independent clauses when a comma would be incorrect; here the second clause is not independent, so the comma-after pattern is correct. The original College Board answer B indicates that "Japan, respectively;" is treated as the best fit given the sentence structure.)
**Choice A is incorrect.** It uses a comma after "Japan" and a trailing comma after "respectively," creating two consecutive commas with no clause break and leaving the following clause improperly connected; Standard English requires clearer separation or a single comma pair bracketing the parenthetical.
**Choice C is incorrect.** It uses a semicolon before "respectively" and a comma after it; a semicolon should not separate the list item from the parenthetical adverb "respectively."
**Choice D is incorrect.** It omits the final comma after "respectively," failing to set off the parenthetical adverb and thus violating the convention that "respectively" be enclosed by commas when inserted into a sentence.
**Faster approach:** When "respectively" interrupts or follows a list, treat it as a parenthetical: place commas on both sides. Scan the sentence to confirm whether the following words form an independent clause; if not, use commas to enclose "respectively."'),
  ('12e8a9cf-c8d4-5cbb-b99c-0adfa48d832d', 1, null, '**Choice B is correct.** The sentence before the blank ends with a quoted song title, including the closing quotation mark and comma: “Rapper’s Delight,” and the conjunction "however" joins the clause that follows, so a semicolon after "however" correctly links the contrasting independent clause that follows ("he joined the label after the song’s release"). The sequence “Delight,” however; produces a correct punctuation pattern: closing quotation + comma, transitional adverb, semicolon to connect two closely related independent clauses while emphasizing contrast.
**Choice A is incorrect.** It uses a comma after "however" (i.e., “Delight,” however,) which leaves only a comma to join the two independent clauses; that creates a comma splice because two independent clauses cannot be joined by just a comma and a transitional adverb.
**Choice C is incorrect.** It places a period before "However," resulting in two separate sentences: one ending with a sentence fragment (“he joined the label after the song’s release” is an independent clause, but the placement of "However," with a capital H implies the following clause is separate). The punctuation shown (“Delight.” However,) is awkward because "However" should be followed by a comma only when it begins the next sentence, but the punctuation in the choice disrupts the intended close contrast and flow.
**Choice D is incorrect.** It omits necessary punctuation after the quotation and before "however" (“Delight” however). Without a comma or semicolon, it fails to mark the transition properly and creates a run-on or mispunctuated sentence.
**Faster approach:** When a quoted title ends a clause and a transitional adverb (however, therefore, meanwhile) introduces a contrasting independent clause, look for a semicolon after the transitional adverb to join the two independent clauses correctly—this pattern reliably signals the correct punctuation choice.'),
  ('5ccbbbdd-ec3d-51d8-98c4-609b54ff17e7', 3, null, '**Choice D is correct.** The sentence in the first clause says the two volcanoes "may look similar from afar," so the second clause needs a word that signals contrast; "though" provides that contrast: "Tehnuka Ilanko and other volcanologists, though, can tell by how each was formed..." This shows that despite superficial similarity, experts can distinguish the two types.
**Choice A is incorrect.** "In addition" suggests adding information, not contrasting appearances with expert knowledge, so it doesn’t fit the contrast needed.
**Choice B is incorrect.** "Therefore" indicates a conclusion or result; the sentence is not drawing a causal conclusion from the first clause, so it is inappropriate.
**Choice C is incorrect.** "For example" would introduce an instance, but the sentence instead needs to signal contrast between appearance and expert assessment.
**Faster approach:** Look for whether the first clause sets up similarity or contrast; pick a transition that matches that relationship (contrast words like "though/ however" for differences, additive words for continuation, etc.).'),
  ('73e90933-3e8c-5cdd-9217-669985d74c59', 0, null, '**Choice A is correct.** The sentence sets up a condition (the light is infrared) that explains why the JWST will perform better than Hubble; "consequently" signals the logical result of that condition. Reading the sentence as "When light ... is infrared, consequently the JWST can provide sharp images" clearly links the cause (infrared light and JWST optimization) to the effect (better images), so the transition is appropriate and logical.
**Choice B is incorrect.** "Admittedly" introduces a concession and would conflict with the positive cause-and-effect relationship here; nothing in the context calls for conceding a point.
**Choice C is incorrect.** "Actually" implies a corrective or unexpected fact; the passage instead explains an expected result of JWST’s infrared optimization, so a corrective tone is inappropriate.
**Choice D is incorrect.** "In addition" would add another fact rather than indicate the result of the condition introduced by "When," so it fails to convey the cause-and-effect relation needed.
**Faster approach:** Identify whether the sentence needs a result, concession, correction, or simple addition; match that to the transition (here, result → "consequently").'),
  ('04d54a08-c8ce-5dc9-a121-98198af837b7', 3, null, '**Choice D is correct.** The notes state that many of the roughly 500 surviving Stradivarius violins are named for a previous owner and that the Jules Falk Stradivarius is named for Jules Falk; combining those statements shows that this instrument was named for its former owner, Jules Falk.
**Choice A is incorrect.** While the notes say Jules Falk was an American violinist, that fact alone doesn’t explain how the instrument got its name.
**Choice B is incorrect.** This choice gives information about the number of violins made and surviving but does not connect to why the Jules Falk Stradivarius has that particular name.
**Choice C is incorrect.** This fragment states who designed Stradivarius violins and that they are renowned, but it fails to explain the origin of the instrument’s name.
**Faster approach:** Look for the answer that explicitly links the instrument’s name to a former owner—combine the general statement that many violins are named for prior owners with the specific note that this violin is named for Jules Falk.'),
  ('01586edc-d753-535c-af92-023bbcad8b09', 2, null, '**Choice C is correct.** It directly and succinctly uses the given notes to state both when and where Argentum debuted: “In 2018” and “in New York City, New York,” matching the student’s information about the work’s 2018 debut at the Bronx Museum in New York City.
**Choice A is incorrect.** It introduces details not in the notes ("cut and imposing"), misstates emphasis by focusing on the sculpture’s appearance and size rather than clearly specifying when and where it debuted.
**Choice B is incorrect.** It makes a generalization about the artist’s materials and scale but says nothing about the date or location of Argentum’s debut.
**Choice D is incorrect.** Although it mentions the year in brackets, it buries the date in parenthetical style and emphasizes the artist’s typical materials rather than clearly stating when and where Argentum debuted.
**Faster approach:** For questions asking to emphasize a specific detail (time/place), choose the option that places the date and location directly and immediately in the sentence—avoid choices that bury or obscure those details with extra description.'),
  ('dc339a54-68cb-546d-aaa9-485a85df1d39', 2, null, '**Choice C is correct.** It directly uses the given notes to state that "two young men are depicted in the bottom left and upper right corners of the canvas," which most effectively emphasizes the specific locations of the figures in Lost in the Shuffle.
**Choice A is incorrect.** Although it compares size, it focuses on dimensions rather than the location of the figures, so it doesn’t emphasize placement within the painting.
**Choice B is incorrect.** It describes the colors of the water in both paintings, not the positions of the figures in Lost in the Shuffle.
**Choice D is incorrect.** It discusses mood common to Rawles’s works rather than the specific locations of the figures.
**Faster approach:** For location questions, pick the choice that repeats the exact positional details (corner, side, center) given in the passage.'),
  ('89bdc687-b6c4-583c-a189-d449f0b8d154', 3, null, '**Choice D is correct.** It explicitly gives the dates for both specimens—June 1930 for Trixis antimenorrhoea and May 1929 for Stephanomeria thurberi—and places them in sequence, which most clearly emphasizes when she collected both samples.
**Choice A is incorrect.** It focuses on the current location of her many samples rather than specifying when the two particular specimens were collected.
**Choice B is incorrect.** It contrasts locations and notes family membership but does not provide the collection dates for either specimen.
**Choice C is incorrect.** It gives the date for only the Trixis specimen (June 26, 1930) and omits the date for the Stephanomeria, so it does not emphasize when both were collected.
**Faster approach:** For questions asking which choice emphasizes timing, scan choices for explicit dates or temporal words (months, years, sequence words like "after") and eliminate options that lack both dates.')
on conflict (question_id) do update set correct_index = excluded.correct_index, correct_answers = excluded.correct_answers,
  explanation = excluded.explanation;
